<?php
require __DIR__.'/../app/bootstrap.php';$admin=require_admin();
$stats=one("SELECT (SELECT COUNT(*) FROM products WHERE is_active=1) AS products,(SELECT COUNT(*) FROM users WHERE role='customer') AS users,(SELECT COUNT(*) FROM orders) AS orders,(SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed') AS revenue");
$recent=all('SELECT id,order_code,customer_name,total,status,created_at FROM orders ORDER BY id DESC LIMIT 8');
$low=all('SELECT id,name,stock FROM products WHERE is_active=1 AND stock<=10 ORDER BY stock ASC,id DESC LIMIT 7');
$admin_title='Tổng quan cửa hàng';$admin_menu='dashboard';require __DIR__.'/partials/header.php';
?>
