<div class="admin-grid-2"><section class="admin-panel"><div class="admin-toolbar"><h2 style="margin:0">Đơn hàng gần đây</h2><a class="btn btn-outline" href="<?= url('admin/orders.php') ?>">Xem tất cả</a></div><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Giá trị</th><th>Trạng thái</th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td><a href="<?= url('admin/order_detail.php?id='.$o['id']) ?>" style="color:var(--mint)"><?= e($o['order_code']) ?></a></td><td><?= e($o['customer_name']) ?></td><td><?= money($o['total']) ?></td><td><span class="status <?= e($o['status']) ?>"><?= e(format_order_status($o['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table><?php if(!$recent):?><p class="admin-empty">Chưa có đơn hàng.</p><?php endif;?></section><section class="admin-panel"><h2>Tồn kho cần chú ý</h2><?php foreach($low as $p):?><div class="summary-row"><span><?= e(cut($p['name'],25)) ?></span><strong style="color:var(--amber)"><?= (int)$p['stock'] ?> còn</strong></div><?php endforeach;?><?php if(!$low):?><p class="admin-empty">Tồn kho các sản phẩm đang ổn.</p><?php endif;?><a href="<?= url('admin/products.php') ?>" class="btn btn-outline" style="margin-top:20px">Quản lý kho</a></section></div>
